import{_ as a,a0 as s,w as T,s as l,ao as p,I as r,x as e,a1 as o,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const f=JSON.parse('{"title":"Linux 有问必答：如何在wget中禁用HTTP转发 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 有问必答：如何在wget中禁用HTTP转发 | LCTT (201411) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 有问必答：如何在wget中禁用HTTP转发 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 有问必答：如何在wget中禁用HTTP转发 | LCTT (201411) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201411/20141105 Linux FAQs with Answers--How to disable HTTP redirect in wget","title":"Linux 有问必答：如何在wget中禁用HTTP转发","tag":"201411","desc":""},"relativePath":"201411/20141105 Linux FAQs with Answers--How to disable HTTP redirect in wget.md","filePath":"[post].md"}'),d={name:"201411/20141105 Linux FAQs with Answers--How to disable HTTP redirect in wget.md"};function w(m,t,u,g,L,x){const n=s("Link");return T(),l("div",null,[t[11]||(t[11]=p(`<h1 id="linux-有问必答-如何在wget中禁用http转发" tabindex="-1">Linux 有问必答：如何在wget中禁用HTTP转发 <a class="header-anchor" href="#linux-有问必答-如何在wget中禁用http转发" aria-label="Permalink to “Linux 有问必答：如何在wget中禁用HTTP转发”">​</a></h1><blockquote><p><strong>提问</strong>： 当我用wget获取一个重定向到URL Y的URL X的时候，wget默认会自动获取URL Y。然而我想要强制获取不带重定向的URL X。我该如何禁用wget重定向URL的功能。</p></blockquote><p>在HTTP标准中，重定向响应（带3XX的HTTP响应）说明请求的URL被移到了新的位置。重定向相应接着包含了目标重定向的URL。</p><p>像常规的HTTP客户端，wget支持URL重定向（也叫URL转发），意味着当你尝试下载一个重定向的URL时，wget会自动跟随URL重定向获取重定向后的资源。如果你由于一些原因想要禁用URL重定向，并停止3XX的状态码，你可以使用wget的“--max-redirect=number”选项。这个选项用来指定最大（递归）重定向的数字，默认是20。</p><p>如果你想要禁用wget中的HTTP重定向，使用“--max-redirect=0”</p><pre><code>$ wget --max-redirect=0 http://www.aaa.com/a.html
</code></pre><hr><pre><code>--2014-10-31 23:08:58--  http://www.aaa.com/a.html
Resolving aaa.com (aaa.com)... 1.2.3.4
Connecting to aaa.com (aaa.com)|1.2.3.4|:80... connected.
HTTP request sent, awaiting response... 301 Moved Permanently
Location: http://www.bbb.com/b.html [following]
0 redirections exceeded.
</code></pre><p>如你所见，当wget遇到HTTP重定向响应时，它不会跟着重定向，并以“0 redirections exceeded”（超出0次重定向）的错误信息停止。它同样会显示一个HTTP的状态码（比如301）。</p><p>注意一下curl，另外一个类似的HTTP客户端，行为正好相反。默认上，curl并不会跟随URL重定向。要强制使cutl重定向到一个URL，你要使用“-L”选项。</p><hr>`,11)),r("p",null,[t[1]||(t[1]=e("via: ",-1)),o(n,{href:"http://ask.xmodulo.com/disable-http-redirect-wget.html"},{default:i(()=>[...t[0]||(t[0]=[e("http://ask.xmodulo.com/disable-http-redirect-wget.html",-1)])]),_:1})]),r("p",null,[t[4]||(t[4]=e("译者：",-1)),o(n,{href:"https://github.com/geekpi"},{default:i(()=>[...t[2]||(t[2]=[e("geekpi",-1)])]),_:1}),t[5]||(t[5]=e(" 校对：",-1)),o(n,{href:"https://github.com/wxy"},{default:i(()=>[...t[3]||(t[3]=[e("wxy",-1)])]),_:1})]),r("p",null,[t[8]||(t[8]=e("本文由 ",-1)),o(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[6]||(t[6]=[e("LCTT",-1)])]),_:1}),t[9]||(t[9]=e(" 原创翻译，",-1)),o(n,{href:"http://linux.cn/"},{default:i(()=>[...t[7]||(t[7]=[e("Linux中国",-1)])]),_:1}),t[10]||(t[10]=e(" 荣誉推出",-1))])])}const c=a(d,[["render",w]]);export{f as __pageData,c as default};
